export type ReturnTypeFunc = (returns?: void) => unknown;
export interface BaseTypeOptions {
  nullable?: boolean | "items" | "itemsAndList";
  defaultValue?: any;
}
export interface FieldOptions extends BaseTypeOptions {
  name?: string;
  description?: string;
  deprecationReason?: string;
  complexity?: number;
}

/** A root query field: the decorated method resolves it. */
export declare function Query(): MethodDecorator;
export declare function Query(name: string): MethodDecorator;
export declare function Query(name: string, options: FieldOptions): MethodDecorator;
export declare function Query(typeFunc: ReturnTypeFunc, options?: FieldOptions): MethodDecorator;

/** A root mutation field. */
export declare function Mutation(): MethodDecorator;
export declare function Mutation(name: string): MethodDecorator;
export declare function Mutation(name: string, options: FieldOptions): MethodDecorator;
export declare function Mutation(typeFunc: ReturnTypeFunc, options?: FieldOptions): MethodDecorator;

/** A root subscription field. */
export declare function Subscription(): MethodDecorator;
export declare function Subscription(name: string): MethodDecorator;
export declare function Subscription(name: string, options: FieldOptions): MethodDecorator;
export declare function Subscription(typeFunc: ReturnTypeFunc, options?: FieldOptions): MethodDecorator;

/** A field of an object type, not a root operation. */
export declare function ResolveField(): MethodDecorator;
export declare function ResolveField(name: string): MethodDecorator;

/** Marks a class of resolvers. */
export declare function Resolver(): ClassDecorator;
export declare function Resolver(typeFunc: ReturnTypeFunc): ClassDecorator;
